1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.Locale;
7	
8	import net.officefloor.plugin.variable.Val;
9	import org.springframework.samples.petclinic.model.Owner;
10	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
11	
12	/**
13	 * Step of {@code POST /api/owners} that assigns the deterministic {@code householdId}. The id is
14	 * derived from the normalized lastName and the postcode, so any two owners with the same lastName
15	 * and postcode are automatically given the identical identifier and are treated as one household.
16	 * It is one component of the consolidated {@link OwnerIdentityKey}. The id no longer depends on
17	 * {@code sharesHousehold} (which now only bypasses the household duplicate block). Owners with no
18	 * postcode have no household and are left with no householdId.
19	 */
20	public class AssignHouseholdId {
21	
22	    public void service(@Val OwnerFieldsDto request, @Val Owner owner) {
23	        owner.setHouseholdId(forRequest(request));
24	    }
25	
26	    /**
27	     * The householdId a create request maps to: the deterministic id for its {@code lastName} and
28	     * {@code postcode}, or {@code null} when no postcode is supplied (no household).
29	     */
30	    static String forRequest(OwnerFieldsDto request) {
31	        String postcode = request.getPostcode();
32	        if (postcode == null || postcode.isBlank()) {
33	            return null;
34	        }
35	        return householdId(request.getLastName(), postcode);
36	    }
37	
38	    /** Stable identifier for the household sharing {@code lastName} at {@code postcode}. */
39	    static String householdId(String lastName, String postcode) {
40	        String key = normalize(lastName) + "|" + (postcode == null ? "" : postcode);
41	        return "HH-" + sha256Hex(key).substring(0, 12).toUpperCase(Locale.ROOT);
42	    }
43	
44	    /** Trim, collapse internal whitespace runs to a single space, and lower-case for comparison. */
45	    private static String normalize(String value) {
46	        if (value == null) {
47	            return "";
48	        }
49	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
50	    }
51	
52	    private static String sha256Hex(String value) {
53	        try {
54	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
55	            StringBuilder sb = new StringBuilder(digest.length * 2);
56	            for (byte b : digest) {
57	                sb.append(String.format("%02x", b));
58	            }
59	            return sb.toString();
